<?php
declare(strict_types=1);
namespace App\Controllers;
use App\Core\{Controller,Request,Response};
final class AttachmentPreviewController extends Controller{
public function note(Request$r):Response{$id=(int)$r->route('id');$u=(int)user()['id'];$row=$this->app->database()->query("SELECT n.attachment_path FROM class_notes n WHERE n.id=:id AND (n.created_by=:u OR (:admin=1 AND EXISTS(SELECT 1 FROM institute_users iu WHERE iu.user_id=:u2 AND iu.institute_id=n.institute_id)) OR (n.status='published' AND EXISTS(SELECT 1 FROM student_accounts sa JOIN students s ON s.id=sa.student_id WHERE sa.user_id=:u3 AND s.institute_id=n.institute_id AND (n.audience_type='all' OR (n.audience_type='class' AND EXISTS(SELECT 1 FROM class_note_classes nc WHERE nc.note_id=n.id AND nc.class_id=s.class_id)) OR (n.audience_type='student' AND s.id=n.student_id)))) OR (n.audience_type='class' AND EXISTS(SELECT 1 FROM employee_accounts ea JOIN teacher_assignments ta JOIN class_note_classes nc ON nc.class_id=ta.class_id AND nc.note_id=n.id WHERE ea.user_id=:u4 AND ta.employee_id=ea.employee_id AND ta.institute_id=n.institute_id AND ta.status='active'))) LIMIT 1",['id'=>$id,'u'=>$u,'admin'=>can('*')?1:0,'u2'=>$u,'u3'=>$u,'u4'=>$u])->fetch();return$this->file($row['attachment_path']??null);}
public function question(Request$r):Response{$id=(int)$r->route('id');$u=(int)user()['id'];$row=$this->app->database()->query("SELECT q.attachment_path FROM online_test_questions q JOIN online_tests t ON t.id=q.test_id WHERE q.id=:id AND (t.created_by=:u OR (:admin=1 AND EXISTS(SELECT 1 FROM institute_users iu WHERE iu.user_id=:u2 AND iu.institute_id=t.institute_id)) OR (t.status='published' AND EXISTS(SELECT 1 FROM student_accounts sa JOIN students s ON s.id=sa.student_id WHERE sa.user_id=:u3 AND s.institute_id=t.institute_id AND s.class_id=t.class_id))) LIMIT 1",['id'=>$id,'u'=>$u,'admin'=>can('*')?1:0,'u2'=>$u,'u3'=>$u])->fetch();return$this->file($row['attachment_path']??null);}
/** A guardian may open a student's own submission/answer/marked-paper files only once the result has been published to them. */
private const GUARDIAN_RESULT_ACCESS="EXISTS(SELECT 1 FROM guardian_accounts ga JOIN guardian_students gs ON gs.guardian_id=ga.guardian_id WHERE ga.user_id=:u4 AND gs.student_id=x.student_id AND x.published_at IS NOT NULL AND x.visible_to IN('parent','both'))";
public function answer(Request$r):Response{$id=(int)$r->route('id');$index=$r->route('index');$u=(int)user()['id'];$row=$this->app->database()->query("SELECT a.attachment_path,a.attachment_paths_json FROM online_test_answers a JOIN online_test_attempts x ON x.id=a.attempt_id JOIN online_tests t ON t.id=x.test_id WHERE a.id=:id AND (t.created_by=:u OR (:admin=1 AND EXISTS(SELECT 1 FROM institute_users iu WHERE iu.user_id=:u2 AND iu.institute_id=t.institute_id)) OR EXISTS(SELECT 1 FROM student_accounts sa WHERE sa.user_id=:u3 AND sa.student_id=x.student_id) OR ".self::GUARDIAN_RESULT_ACCESS.") LIMIT 1",['id'=>$id,'u'=>$u,'admin'=>can('*')?1:0,'u2'=>$u,'u3'=>$u,'u4'=>$u])->fetch();$paths=json_decode((string)($row['attachment_paths_json']??''),true);if(!is_array($paths)||!$paths)$paths=$row['attachment_path']?[$row['attachment_path']]:[];return$this->file($paths[(int)($index??0)]??null);}
public function paper(Request$r):Response{$id=(int)$r->route('id');$index=(int)$r->route('index');$u=(int)user()['id'];$row=$this->app->database()->query("SELECT x.submission_files_json FROM online_test_attempts x JOIN online_tests t ON t.id=x.test_id WHERE x.id=:id AND (t.created_by=:u OR (:admin=1 AND EXISTS(SELECT 1 FROM institute_users iu WHERE iu.user_id=:u2 AND iu.institute_id=t.institute_id)) OR EXISTS(SELECT 1 FROM student_accounts sa WHERE sa.user_id=:u3 AND sa.student_id=x.student_id) OR ".self::GUARDIAN_RESULT_ACCESS.") LIMIT 1",['id'=>$id,'u'=>$u,'admin'=>can('*')?1:0,'u2'=>$u,'u3'=>$u,'u4'=>$u])->fetch();$files=json_decode((string)($row['submission_files_json']??''),true)?:[];return$this->file($files[$index]??null);}
/** The teacher's marked/annotated paper, returned to the student and (if published to them) their guardian. */
public function markedPaper(Request$r):Response{$id=(int)$r->route('id');$index=(int)$r->route('index');$u=(int)user()['id'];$row=$this->app->database()->query("SELECT x.marked_files_json FROM online_test_attempts x JOIN online_tests t ON t.id=x.test_id WHERE x.id=:id AND (t.created_by=:u OR (:admin=1 AND EXISTS(SELECT 1 FROM institute_users iu WHERE iu.user_id=:u2 AND iu.institute_id=t.institute_id)) OR (EXISTS(SELECT 1 FROM student_accounts sa WHERE sa.user_id=:u3 AND sa.student_id=x.student_id) AND x.published_at IS NOT NULL AND x.visible_to IN('student','both')) OR ".self::GUARDIAN_RESULT_ACCESS.") LIMIT 1",['id'=>$id,'u'=>$u,'admin'=>can('*')?1:0,'u2'=>$u,'u3'=>$u,'u4'=>$u])->fetch();$files=json_decode((string)($row['marked_files_json']??''),true)?:[];return$this->file($files[$index]??null);}
public function announcement(Request$r):Response{$id=(int)$r->route('id');$u=(int)user()['id'];$roles=(array)(user()['roles']??[]);$audiences=['all'];if(in_array('student',$roles,true))$audiences[]='students';if(in_array('parent',$roles,true))$audiences[]='parents';if(in_array('employee',$roles,true))$audiences[]='employees';if(in_array('teacher',$roles,true)){$audiences[]='employees';$audiences[]='teachers';}$audiences=array_values(array_unique($audiences));$marks=implode(',',array_fill(0,count($audiences),'?'));$sql="SELECT a.image_path FROM announcements a WHERE a.id=? AND (a.created_by=? OR EXISTS(SELECT 1 FROM institute_users iu WHERE iu.user_id=? AND iu.institute_id=a.institute_id) OR (a.status='published' AND a.publish_at<=? AND (a.expires_at IS NULL OR a.expires_at>=?) AND a.audience IN ($marks) AND (EXISTS(SELECT 1 FROM student_accounts sa JOIN students s ON s.id=sa.student_id WHERE sa.user_id=? AND s.institute_id=a.institute_id) OR EXISTS(SELECT 1 FROM guardian_accounts ga JOIN guardians g ON g.id=ga.guardian_id WHERE ga.user_id=? AND g.institute_id=a.institute_id) OR EXISTS(SELECT 1 FROM employee_accounts ea JOIN employees e ON e.id=ea.employee_id WHERE ea.user_id=? AND e.institute_id=a.institute_id)))) LIMIT 1";$stmt=$this->app->database()->connection()->prepare($sql);$now=date('Y-m-d H:i:s');$stmt->execute(array_merge([$id,$u,$u,$now,$now],$audiences,[$u,$u,$u]));$row=$stmt->fetch();return$this->file($row['image_path']??null);}
private function file(?string$relative):Response{if(!$relative)return Response::html('Attachment not found',404);$root=realpath(BASE_PATH.'/storage/uploads');$path=realpath(BASE_PATH.'/'.$relative);if(!$root||!$path||!str_starts_with($path,$root.DIRECTORY_SEPARATOR)||!is_file($path))return Response::html('Attachment not found',404);$mime=(new \finfo(FILEINFO_MIME_TYPE))->file($path);if(!in_array($mime,['application/pdf','image/jpeg','image/png'],true))return Response::html('Preview unavailable',415);return new Response((string)file_get_contents($path),200,['Content-Type'=>$mime,'Content-Disposition'=>'inline','X-Content-Type-Options'=>'nosniff','Content-Security-Policy'=>"default-src 'none'; img-src 'self' data:; style-src 'unsafe-inline'; sandbox"]);}
}
